// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        // The initial owner is address(0); only that address passes onlyOwner.
        vm.assume(actor == address(0));
        vm.prank(actor);
        c.transferOwnership(newOwner);
        // General rule: a successful transferOwnership sets owner to newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

