// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // The owner of a fresh C is address(0); any other address is a non-owner.
        // Exclude address(0) itself (the legitimate owner) to keep the domain admissible.
        vm.assume(caller != address(0));

        bool ok;
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }

        // General rule: a non-owner's call to owned() must neither succeed nor
        // mutate the ownership state observable through c.owner().
        assertTrue(!ok && c.owner() == address(0), "non-owner call to owned() must revert and leave ownership unchanged");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        // 1. WIDE admissible domain: any caller the fuzzer picks, except trivial address(0),
        //    which is the initial owner and would mask the difference.
        vm.assume(caller != address(0));

        // 2. Set up the scenario: the initial owner (address(0)) hands ownership to the
        //    fuzzed caller, so that owned() is admissible for the caller in the reference.
        vm.prank(address(0));
        c.transferOwnership(caller);

        // Snapshot the owner before the boundary call.
        address before = c.owner();

        // Drive c through `owned` from the fuzzed caller.
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // 3. The single general rule: a call to owned(), whenever it succeeds, must NOT
        //    change the ownership of the contract. The reference satisfies this for every
        //    input (owned() is a no-op). The mutant executes transferOwnership(msg.sender)
        //    inside owned(), writing the owner slot during the call, so for inputs where
        //    that write is observable the post-state differs from the pre-state snapshot.
        assertTrue(ok ? (c.owner() == before) : (c.owner() == before),
            "owned() must never change ownership");
    }
}
